package br.com.onda;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.SystemClock;import android.widget.*;import androidx.core.content.FileProvider;import org.json.*;import org.junit.*;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;import java.io.*;import java.lang.reflect.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.*;
@androidx.media3.common.util.UnstableApi
public class BackupRecoveryTest {
 private final android.app.Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private BackupActivity activity;private String downloaded,lists,phrases;private Set<String> favorites;private Uri source;private String title;
 @Before public void prepare()throws Exception{downloaded=c.getSharedPreferences("downloaded_audio",0).getString("documents","{}");lists=c.getSharedPreferences("playlists",0).getString("lists","[]");phrases=c.getSharedPreferences("voice_phrases",0).getString("entries","[]");favorites=new HashSet<>(c.getSharedPreferences("library",0).getStringSet("favorites",Collections.emptySet()));JSONObject info=new JSONObject(new String(Files.readAllBytes(new File(c.getFilesDir(),"legacy-download-info.json").toPath()),StandardCharsets.UTF_8));source=Uri.parse(info.getString("uri"));title=info.getString("title");DownloadedAudio.remember(c,source.toString(),title,"audio/wav");}
 @After public void restore(){if(activity!=null){ins.runOnMainSync(()->activity.finish());ins.waitForIdleSync();}c.getSharedPreferences("downloaded_audio",0).edit().putString("documents",downloaded).commit();c.getSharedPreferences("playlists",0).edit().putString("lists",lists).commit();c.getSharedPreferences("voice_phrases",0).edit().putString("entries",phrases).commit();c.getSharedPreferences("library",0).edit().putStringSet("favorites",favorites).commit();}
 private Object get(String field)throws Exception{Field f=BackupActivity.class.getDeclaredField(field);f.setAccessible(true);return f.get(activity);}
 private void idle()throws Exception{long end=SystemClock.elapsedRealtime()+30000;while((Boolean)get("busy")&&SystemClock.elapsedRealtime()<end)Thread.sleep(60);assertFalse((Boolean)get("busy"));ins.waitForIdleSync();}
 private void launch(){activity=(BackupActivity)ins.startActivitySync(new Intent(c,BackupActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ins.waitForIdleSync();}
 @Test public void usbRecoveredMetadataMapsBothLegacyNumericAndDownloadedFavorites()throws Exception{String raw=new String(Files.readAllBytes(new File(c.getFilesDir(),"usb-recovered.json").toPath()),StandardCharsets.UTF_8);BackupData.Archive a=BackupData.parse(raw);assertEquals(2,a.favorites.size());BackupData.Plan p=BackupStore.plan(c,a,BackupStore.tracks(c));assertEquals(2,p.matched);assertEquals(0,p.missing);assertEquals(0,p.ambiguous);BackupStore.apply(c,p);assertTrue(c.getSharedPreferences("library",0).getStringSet("favorites",Collections.emptySet()).contains(DownloadedAudio.id(source.toString())));}
 @Test public void newExportAcceptsTinyDownloadedFavoriteThatOldExporterRejected()throws Exception{c.getSharedPreferences("library",0).edit().putStringSet("favorites",Collections.singleton(DownloadedAudio.id(source.toString()))).commit();PlaylistStore.save(c,Collections.emptyList());File file=new File(ImageSharing.folder(c),"backup-download-test.json");try{launch();Uri uri=FileProvider.getUriForFile(c,c.getPackageName()+".share",file);ins.runOnMainSync(()->activity.onActivityResult(801,Activity.RESULT_OK,new Intent().setData(uri)));idle();String raw=new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8);assertTrue(raw.length()<8192);assertEquals(1,BackupData.parse(raw).favorites.size());assertEquals(0,BackupData.parse(raw).tracks.get(0).duration);assertTrue(((TextView)get("status")).getText().toString().contains("Backup exportado"));android.graphics.Bitmap shot=ins.getUiAutomation().takeScreenshot();try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"backup-recovery.png"))){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{shot.recycle();}}finally{file.delete();}}
 @Test public void importLargerThanEightMbReachesPreviewWithoutMisleadingSizeFailure()throws Exception{File file=new File(ImageSharing.folder(c),"backup-nine-mb.json");try{byte[] base=Files.readAllBytes(new File(c.getFilesDir(),"usb-recovered.json").toPath());try(OutputStream out=new FileOutputStream(file)){byte[] blank=new byte[1024*1024];Arrays.fill(blank,(byte)' ');for(int i=0;i<9;i++)out.write(blank);out.write(base);}launch();Uri uri=FileProvider.getUriForFile(c,c.getPackageName()+".share",file);ins.runOnMainSync(()->activity.onActivityResult(802,Activity.RESULT_OK,new Intent().setData(uri)));idle();assertTrue(((TextView)get("status")).getText().toString(),((TextView)get("status")).getText().toString().contains("Backup válido"));ins.getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK);}finally{file.delete();}}
}
